# slugify :: 'Hello, World!'
import re

def slugify(s):
    return re.sub(r"[\s_-]+", "-", re.sub(r"[^a-z0-9\s_-]", "", s.lower()).strip()).strip("-")

if __name__ == "__main__":
    print(slugify('Hello, World!'))

